INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Zielt Adressmanagement auf IP-Sparsamkeit ab?', 2, '[{"text": "Ja", "correct": true, "because": "Optimiert Adressnutzung"}, {"text": "Nein", "correct": false, "because": "Hauptziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode fördert IP-Sparsamkeit bei 192.168.1.0/24?', 3, '[{"text": "Subnetting", "correct": true, "because": "Teilt Adressen effizient"}, {"text": "Statische Vergabe", "correct": false, "because": "Weniger flexibel"}, {"text": "Zufällige Zuweisung", "correct": false, "because": "Verschwendet Adressen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kleinere Subnetze sparen IPs. b) IP-Sparsamkeit erhöht die Bandbreite.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist unabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Adressmanagement für IP-Sparsamkeit?', 4, '[{"text": "Subnetzgröße", "correct": false, "because": "Bestimmt Effizienz"}, {"text": "Hostbedarf", "correct": false, "because": "Passt Adressen an"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /30 bei 192.168.1.0/24 IPs spart?', 2, '[{"text": "Ja", "correct": true, "because": "Nur 4 Adressen pro Subnetz"}, {"text": "Nein", "correct": false, "because": "Effiziente Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske ist für 5 Hosts pro Subnetz am sparsamsten?', 3, '[{"text": "/29", "correct": true, "because": "8 Adressen, 6 nutzbar"}, {"text": "/28", "correct": false, "because": "16 Adressen, zu groß"}, {"text": "/30", "correct": false, "because": "4 Adressen, zu klein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praktiken fördern IP-Sparsamkeit?', 5, '[{"text": "Subnetting", "correct": true, "because": "Optimiert Adressnutzung"}, {"text": "DHCP mit kleinem Pool", "correct": true, "because": "Begrenzt Vergabe"}, {"text": "Statische IPs für alle", "correct": false, "because": "Verschwendet Adressen"}, {"text": "Große Subnetze", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) /26 spart mehr IPs als /24. b) IP-Sparsamkeit ist nur für große Netze. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) gilt für alle Netze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für IP-Sparsamkeit?', 4, '[{"text": "Hostanzahl", "correct": false, "because": "Passt Subnetze an"}, {"text": "Subnetzmaske", "correct": false, "because": "Definiert Bereiche"}, {"text": "Betriebssystem", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Spart /28 bei 10.0.0.0/24 mehr IPs als /26?', 2, '[{"text": "Ja", "correct": true, "because": "16 vs. 64 Adressen pro Subnetz"}, {"text": "Nein", "correct": false, "because": "Kleinere Subnetze sparen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Adressen spart /29 im Vergleich zu /28 bei einem Subnetz?', 4, '[{"text": "8", "correct": true, "because": "16 - 8 = 8 Adressen"}, {"text": "4", "correct": false, "because": "Zu wenig"}, {"text": "16", "correct": false, "because": "Zu viel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass IP-Sparsamkeit nur mit IPv6 nötig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch IPv4 benötigt Sparsamkeit"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für IP-Sparsamkeit?', 3, '[{"text": "Minimale Subnetzgröße", "correct": true, "because": "Reduziert Verschwendung"}, {"text": "Schnelligkeit", "correct": false, "because": "Effizienz zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DHCP hilft bei IP-Sparsamkeit. b) Große Subnetze sind immer effizienter.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft ineffizient"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse fördern IP-Sparsamkeit bei 192.168.1.0/24?', 5, '[{"text": "32 Subnetze mit /29", "correct": true, "because": "8 Adressen pro Subnetz"}, {"text": "64 Subnetze mit /30", "correct": true, "because": "4 Adressen pro Subnetz"}, {"text": "2 Subnetze mit /25", "correct": false, "because": "128 Adressen zu groß"}, {"text": "1 Subnetz mit /24", "correct": false, "because": "Keine Aufteilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei IP-Sparsamkeit unwichtig?', 3, '[{"text": "Subnetzaufteilung", "correct": false, "because": "Optimiert Nutzung"}, {"text": "Hostbedarf", "correct": false, "because": "Passt Subnetze an"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Spart /30 mehr IPs als /29 bei 10 Hosts?', 3, '[{"text": "Nein", "correct": true, "because": "/30 zu klein, /29 passend"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 192.168.1.0/24 mit /28 IPs spart?', 2, '[{"text": "Ja", "correct": true, "because": "16 Adressen pro Subnetz effizient"}, {"text": "Nein", "correct": false, "because": "Kleinere Subnetze sparen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Subnetzgröße spart am meisten bei 3 Hosts pro Subnetz?', 4, '[{"text": "/30", "correct": true, "because": "4 Adressen, 2 nutzbar"}, {"text": "/29", "correct": false, "because": "8 Adressen, zu groß"}, {"text": "/28", "correct": false, "because": "16 Adressen, ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Subnetze sind bei 172.16.0.0/24 mit /27 maximal sparsam?', 3, '[{"text": "8", "correct": true, "because": "2^(27-24) = 8, 32 Adressen pro Subnetz"}, {"text": "4", "correct": false, "because": "Für /26"}, {"text": "16", "correct": false, "because": "Für /28"}]');
